'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','progression-data.js','progression-engine.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);return c.window;}
test('expanded route retains all persisted legacy reading step IDs',()=>{const w=setup(),tasks=w.PHOENIX_ROUTE.tasks;for(const [id,old]of Object.entries({'q-lilac':['1','2','3','4'],'q-beast':['1','2','3','4','5'],'q-incident':['1','2']})){const stages=tasks[id].stages;assert.equal(new Set(stages.map(s=>s.id)).size,stages.length);for(const stage of old)assert.ok(stages.find(s=>s.id===stage),id+'/'+stage);}});
test('contextual route and detour links resolve to canonical tasks and existing reading steps',()=>{const tasks=setup().PHOENIX_ROUTE.tasks;for(const task of Object.values(tasks))for(const s of task.stages||[])for(const l of [...s.links||[],...s.detours||[]]){assert.ok(tasks[l.task],l.task);if(l.stage)assert.ok(tasks[l.task].stages.some(s=>s.id===l.stage),l.task+'/'+l.stage);}});
test('early warning identities resolve to independent activity and quest records',()=>{const w=setup(),tasks=w.PHOENIX_ROUTE.tasks,engine=w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,tasks,w.PHOENIX_ROUTE.hubs),p=engine.init();for(const t of Object.values(tasks))if(t.startWarning){const a=t.startWarning;assert.ok(w.PHOENIX_PROGRESS_DATA.quests[a.untilQuest]);if(a.activity){assert.ok(tasks[a.activity]);const plan=engine.plan(p,{}, {kind:'activity',id:a.activity,value:true});assert.equal(plan.completed[a.activity],true);assert.equal(engine.done(a.untilQuest,plan.progress),false);}}});
test('main story checklist identities stay independent of expanded reading steps',()=>{const w=setup(),q=w.PHOENIX_PROGRESS_DATA.quests;assert.equal(q['q-lilac'].objectives.length,8);assert.equal(q['q-beast'].objectives.length,16);assert.equal(q['q-incident'].objectives.length,1);});
